#!/usr/bin/env python3
"""Run the Java ports against golden vectors generated by the verified Python models (tools/j2me_golden.py).
Usage: python3 tools/j2me_test.py [res dir]   (default work/res -> symlink to the original resources, ASCII path for the JVM)
Writes docs/phaseD_selftest.txt."""
import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, 'tools'))
import j2me_build as B

res = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, 'work', 'res')
gold = os.path.join(ROOT, 'work', 'golden')
os.makedirs(gold, exist_ok=True)
cls = B.compile_main()
B.scan(cls)
tc = B.compile_tests()
env = dict(os.environ, JAVA_TOOL_OPTIONS='')
cp = cls + os.pathsep + tc
out = []


def gen(kind, *extra):
    if not os.path.exists(os.path.join(gold, kind + '.txt')):
        subprocess.run([sys.executable, os.path.join(ROOT, 'tools', 'j2me_golden.py'), kind, res, gold] + list(extra), check=True, env=env)


def java(*args):
    p = subprocess.run(['java', '-cp', cp] + list(args), env=env, capture_output=True, text=True)
    out.append((p.stdout + p.stderr).strip())
    print(out[-1])
    return p.returncode


rc = 0
gen('des')
rc |= java('hl4.test.DesTest', res, os.path.join(gold, 'des.txt'))
gen('blit')
rc |= java('hl4.test.BlitTest', res, os.path.join(gold, 'blit_images.txt'), os.path.join(gold, 'blit.txt'))
gen('parse')
rc |= java('hl4.test.ParseTest', res, os.path.join(gold, 'parse.txt'))
gen('sprite')
rc |= java('hl4.test.SpriteTest', res, gold)
open(os.path.join(ROOT, 'docs', 'phaseD_selftest.txt'), 'w').write('\n'.join(o.replace('Picked up JAVA_TOOL_OPTIONS: \n', '') for o in out) + '\n')
sys.exit(rc)
